import{_ as a,o as e,c as l,a2 as s}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"日常使用与自用报告","description":"","frontmatter":{},"headers":[],"relativePath":"reference/daily-use.md","filePath":"reference/daily-use.md","lastUpdated":1795426969000}'),t={name:"reference/daily-use.md"};function o(n,i,r,d,h,p){return e(),l("div",null,[...i[0]||(i[0]=[s(`<h1 id="日常使用与自用报告" tabindex="-1">日常使用与自用报告 <a class="header-anchor" href="#日常使用与自用报告" aria-label="Permalink to &quot;日常使用与自用报告&quot;">​</a></h1><p>Hearth 现在把“日常操作”和“工程诊断”分开：日常只需要聊天、资料库和 Context；任务状态、审批和失败恢复都出现在对话里的运行卡和右侧产物面板，不再有独立的任务列表或收件箱。</p><h2 id="聊天工作台" tabindex="-1">聊天工作台 <a class="header-anchor" href="#聊天工作台" aria-label="Permalink to &quot;聊天工作台&quot;">​</a></h2><ul><li>左侧是对话列表；项目会话按文件夹分组，可直接新建任务或继续普通对话。</li><li>输入框只保留一个执行器选择器：对话级选择覆盖全局默认；不可用或未绑定时自动回退。</li><li>任务以运行卡内联在时间线里：展开后看到叙述、工具调用、命令、文件与结算状态；任务失败或等待审批时，卡片会给出继续、重试或补充输入入口。</li><li>右侧“对话产物”按需展开：产物、后台任务和附件都在这里，文本、Markdown、代码、JSON/CSV、图片和 PDF 可直接预览。</li></ul><p>审批出现在运行卡内，不需要另开页面。工作区内可逆写入自动执行；shell、删除、邮件、桌面、陌生域名和提交/上传/下载类动作仍需要一次性授权，参数指纹绑定当次动作。</p><h2 id="资料库" tabindex="-1">资料库 <a class="header-anchor" href="#资料库" aria-label="Permalink to &quot;资料库&quot;">​</a></h2><p>左侧导航的 <strong>资料库</strong>（<code>/library</code>）把文件、记忆、资料和技能放在同一棵树里：</p><ul><li>顶部搜索框跨树检索；选中节点后右侧显示摘要、标签和内容预览。</li><li>记忆按“已记住 / 待确认”分区；点开一条记忆可以查看来源、可信度、版本和纠正记录。</li><li>回收站支持恢复或彻底删除；删除记忆会走遗忘传播，其他节点仍引用的内容不会被误删。</li><li>技能页可以查看使用次数、版本和最近一次调用，不是静态说明页。</li></ul><h2 id="context-交接" tabindex="-1">Context 交接 <a class="header-anchor" href="#context-交接" aria-label="Permalink to &quot;Context 交接&quot;">​</a></h2><p>左侧导航的 <strong>Context</strong>（<code>/context</code>）用于把当前工作交给下一个执行者或账号：</p><ul><li>顶部选择范围（全部记忆或单个账号），显示活跃记忆、最近决定、目标和下一步。</li><li>“接手摘要”从记忆生成，原文按条目列出；可以下载原记录和完整 zip。</li><li>共享视图会列出全部记忆和交接范围，便于核对是否漏项。</li><li>导出文件可能包含个人信息，分享前请检查。</li></ul><h2 id="邮件与定时任务" tabindex="-1">邮件与定时任务 <a class="header-anchor" href="#邮件与定时任务" aria-label="Permalink to &quot;邮件与定时任务&quot;">​</a></h2><ul><li><strong>邮件</strong>（<code>/mail</code>）：SMTP 发送复用审批与效果账本；IMAP 只读同步最近邮件到来源，不标记已读。默认写本机发件箱，配置账户后可以提交真实发送审批。</li><li><strong>定时任务</strong>（<code>/schedules</code>）：支持 Cron、有界补跑、失败冷却和直接使用自定义输入；执行结果仍以任务形式进入对话或资料库。</li><li><strong>连接</strong>（<code>/connections</code>）：飞书长连接、浏览器、桌面助手和 MCP 的接入状态都在这里；入站消息带幂等记录，不需要公网回调。</li></ul><h2 id="自用报告-dogfood" tabindex="-1">自用报告（dogfood） <a class="header-anchor" href="#自用报告-dogfood" aria-label="Permalink to &quot;自用报告（dogfood）&quot;">​</a></h2><p><code>npm run dogfood:report</code> 从本地事件账本读最近 7 天：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood:report</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood:report</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hearth-os</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reports/dogfood.md</span></span></code></pre></div><p>报告包含：</p><ul><li>新建任务数、完成/失败/进行中数量；</li><li>成功率（完成 ÷ 已完成和失败）与一次通过率（第一次尝试就完成）；</li><li>尝试次数、轮次、工具调用、输入/输出 token；</li><li>审批次数、通过和拒绝数量；</li><li>最常见的失败原因，以及需要多次尝试的任务。</li></ul><p>指标只描述本机真实使用，不是公开基准。公开评测已迁到独立仓库 <code>hearth-eval</code>，主仓库不再保留评测控制台。报告默认写到 <code>reports/</code>，这个目录用于本机记录，不进入版本库。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><ul><li>聊天时间线只显示用户需要看的摘要和证据；完整轨迹留在本地事件日志与 <code>run-evidence.json</code>，不在界面上倾倒内部 JSON。</li><li>自用报告不推断因果，不把失败归因于模型或用户；失败原因按任务记录原文聚合。</li><li>数据不出本机；报告文件里可能包含任务标题，分享前请自行检查。</li></ul>`,21)])])}const u=a(t,[["render",o]]);export{k as __pageData,u as default};
